        {"kind": "metric", "sql": "SELECT 'abn' p, metric, count(*) n, min(value) mn, max(value) mx FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND attr_k8s_deployment_name='reservation' GROUP BY ALL UNION ALL SELECT 'norm', metric, count(*), min(value), max(value) FROM normal_metrics WHERE metric='k8s.deployment.available' AND attr_k8s_deployment_name='reservation' GROUP BY ALL", "claim": "Reservation deployment availability drops to 0 during the abnormal window, while it was 1 throughout the normal period."}
